<include file="Public:header"/>	<div class="mainbox">		<div id="nav" class="mainnav_title">			<ul>				<a href="{pigcms{:U('index')}" class="on">系统后台日志列表</a>|				<a href="{pigcms{:U('merchant')}">商家后台日志列表</a>|				<a href="{pigcms{:U('house')}">小区后台日志列表</a>|			</ul>		</div>		<table class="search_table" width="100%">			<tr>				<td>					<form action="{pigcms{:U('index')}" method="get">						<input type="hidden" name="c" value="Admin_log"/>						<input type="hidden" name="a" value="index"/>						控制器(MODULE): <input type="text" name="module" class="input-text" value="{pigcms{$_GET['module']}"/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;						方法(ACTION): <input type="text" name="action" class="input-text" value="{pigcms{$_GET['action']}"/>						&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;						内容(CONTENT)(模糊查询，多个以&&分割): <input type="text" name="content" class="input-text" value="{pigcms{$_GET['content']}"/>						&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;						常见页面：<select name="do">							<option value="">无</option>							<volist name="page_tip_arr" id="vo">								<option value="{pigcms{$key}" <if condition="$pageStr eq $key">selected="selected"</if>>{pigcms{$vo.name}</option>							</volist>						</select>						<input type="submit" value="查询" class="button"/>					</form>				</td>			</tr>		</table>		<if condition="$page_tip">			<div class="page_tips">				<ol>					<li>{pigcms{$page_tip.name}<br/>{pigcms{$page_tip.info}</li>				</ol>			</div>		</if>		<form name="myform" id="myform" action="" method="post">			<div class="table-list">				<table width="100%" cellspacing="0">					<thead>						<tr>							<th width="80">日志ID</th>							<th width="80">管理员ID</th>							<th width="80">控制器</th>							<th width="80">方法</th>							<th>内容</th>							<th width="120">操作时间</th>							<th width="120">操作IP</th>						</tr>					</thead>					<tbody>						<if condition="is_array($log_list)">							<volist name="log_list" id="vo">								<tr>									<td>{pigcms{$vo.id}</td>									<td>{pigcms{$vo.admin_id}</td>									<td>{pigcms{$vo.module}</td>									<td>{pigcms{$vo.action}</td>									<td><pre style="width:100%;overflow-x:auto;display:none;">{pigcms{$vo.content|unserialize=###|print_r=###}</pre></td>									<td>{pigcms{$vo.add_time|date='Y-m-d H:i:s',###}</td>									<td>{pigcms{$vo.add_ip}</td>								</tr>							</volist>							<tr><td class="textcenter pagebar" colspan="7">{pigcms{$pagebar}</td></tr>						<else/>							<tr><td class="textcenter red" colspan="7">列表为空！</td></tr>						</if>					</tbody>				</table>			</div>		</form>	</div>	<script>		$('pre').each(function(){			$(this).width($(this).closest('td').width()).show();		});	</script><include file="Public:footer"/>